<?php require 'includes/bootstrap.php'; $page_title='Каталог недвижимости'; $favoriteIds=favorite_ids($pdo); $where=["status='active'"]; $params=[]; $typeMap=['Квартира'=>'Apartment','Дом'=>'House','Вилла'=>'Villa','Лофт'=>'Loft']; foreach(['city'=>'city','type'=>'type'] as $q=>$col) if(!empty($_GET[$q])){$where[]="$col LIKE ?";$value=trim($_GET[$q]);$params[]='%'.($q==='type'?($typeMap[$value]??$value):$value).'%';} foreach(['min_price'=>['price','>='],'max_price'=>['price','<='],'rooms'=>['rooms','>='],'min_area'=>['area','>='] ] as $q=>$rule) if(isset($_GET[$q])&&$_GET[$q]!==''){$where[]="$rule[0] $rule[1] ?";$params[]=(float)$_GET[$q];} $sort=['new'=>'created_at DESC','cheap'=>'price ASC','expensive'=>'price DESC'][$_GET['sort']??'new']??'created_at DESC'; $st=$pdo->prepare('SELECT * FROM properties WHERE '.implode(' AND ',$where).' ORDER BY '.$sort);$st->execute($params);$properties=$st->fetchAll();require 'includes/header.php'; ?>
<main class="container section"><p class="eyebrow">Изучите нашу коллекцию</p><h1>Недвижимость</h1><form class="filters" method="get"><input name="city" value="<?=e($_GET['city']??'')?>" placeholder="Город"><select name="type"><option value="">Все типы</option><?php foreach(['Квартира','Дом','Вилла','Лофт'] as $x): ?><option <?=$x===($_GET['type']??'')?'selected':''?>><?=$x?></option><?php endforeach ?></select><input type="number" name="min_price" value="<?=e($_GET['min_price']??'')?>" placeholder="Цена от"><input type="number" name="max_price" value="<?=e($_GET['max_price']??'')?>" placeholder="Цена до"><input type="number" name="rooms" value="<?=e($_GET['rooms']??'')?>" placeholder="Комнат от"><input type="number" name="min_area" value="<?=e($_GET['min_area']??'')?>" placeholder="Площадь от, м²"><select name="sort"><option value="new">Сначала новые</option><option value="cheap" <?=($_GET['sort']??'')==='cheap'?'selected':''?>>Сначала дешёвые</option><option value="expensive" <?=($_GET['sort']??'')==='expensive'?'selected':''?>>Сначала дорогие</option></select><button>Применить фильтры</button></form><p class="result-count">Найдено объектов: <?=count($properties)?></p><div class="property-grid"><?php foreach($properties as $p) require 'includes/property-card.php'; ?></div><?php if(!$properties): ?><div class="empty"><h2>Подходящих объектов нет</h2><p>Попробуйте изменить параметры поиска.</p></div><?php endif ?></main><?php require 'includes/footer.php'; ?>
